import { Component, inject, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FinancialService } from '../../core/services/financial.service';
import { FinancialTableComponent } from '../../shared/components/financial-table/financial-table.component';
import { KpiCardComponent } from '../../shared/components/kpi-card/kpi-card.component';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, FinancialTableComponent, KpiCardComponent],
  templateUrl: './dashboard.component.html'
})
export class DashboardComponent {
  financialService = inject(FinancialService);
  Object = Object;

  // ETAPA 6: Lógica para Pontos Positivos Dinâmicos
  pontosPositivos = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    
    const items: string[] = [];
    const ind = data.indices;

    if (ind['margem_liquida'] > 10) items.push('✅ Margem Líquida sólida acima de 10%, indicando alta eficiência operacional.'); 
    if (ind['roa'] > 15) items.push('✅ Excelente retorno sobre ativos (ROA), demonstrando uso eficiente da estrutura.'); 
    if (ind['roe'] > 20) items.push('✅ Retorno sobre Patrimônio (ROE) atrativo para investidores e sócios.');

    const lucroLiq = data.tabela_dre?.find(r => r.conta.toLowerCase().includes('lucro do exercicio'));
    if (lucroLiq && lucroLiq.perc > 0) {
      items.push(`✅ Crescimento de ${lucroLiq.perc}% no Lucro Líquido comparado ao período anterior.`);
    }

    return items;
  });

  // ETAPA 6: Lógica para Pontos de Atenção Dinâmicos
  pontosAtencao = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    
    const items: string[] = [];
    const ind = data.indices;

    if (ind['liq_corrente'] < 1.0) items.push('⚠️ Liquidez corrente abaixo de 1.0 indica risco imediato de insolvência.'); 
    if (ind['liq_imediata'] < 0.1) items.push('⚠️ Liquidez imediata crítica: dependência total de recebíveis futuros para pagar dívidas de hoje.');
    if (ind['endiv_geral'] > 70) items.push('⚠️ Endividamento Geral crítico acima de 70%, comprometendo a autonomia financeira.'); 

    return items;
  });

  // ETAPA 4: Cores dinâmicas atualizadas com os novos indicadores
  getIndicatorClass(key: string, value: number): string {
    const k = key.toLowerCase();
    
    // Regras para Liquidez (Corrente, Seca e Imediata)
    if (k.includes('liq_')) {
      const threshold = k.includes('imediata') ? 0.2 : 1.0;
      if (value < threshold) return 'text-rose-600 bg-rose-50 border-rose-100';
      if (value <= threshold + 0.5) return 'text-amber-600 bg-amber-50 border-amber-100';
      return 'text-emerald-600 bg-emerald-50 border-emerald-100';
    }
    
    if (k.includes('endiv_geral')) {
      if (value > 70) return 'text-rose-600 bg-rose-50 border-rose-100';
      if (value > 50) return 'text-amber-600 bg-amber-50 border-amber-100';
      return 'text-emerald-600 bg-emerald-50 border-emerald-100';
    }

    if (k.includes('margem_liquida') || k.includes('roe') || k.includes('roa')) {
      if (value < 0) return 'text-rose-600 bg-rose-50 border-rose-100';
      if (value < 10) return 'text-amber-600 bg-amber-50 border-amber-100';
      return 'text-emerald-600 bg-emerald-50 border-emerald-100';
    }

    return 'text-slate-600 bg-slate-50 border-slate-100';
  }

  // ETAPA 4: Texto interpretativo dinâmico para os novos cards
  getIndicatorNote(key: string, value: number): string {
    const k = key.toLowerCase();
    
    if (k.includes('liq_corrente')) {
      if (value < 1.0) return '🚨 CRÍTICO: Insolvência a curto prazo';
      return value <= 1.5 ? '⚠️ ATENÇÃO: Capacidade justa' : '✅ BOM: Capacidade adequada';
    }

    if (k.includes('liq_seca')) {
      if (value < 1.0) return '🚨 CRÍTICO: Depende de estoques';
      return '✅ BOM: Solvência sem estoques';
    }

    if (k.includes('liq_imediata')) {
      return value < 0.1 ? '🚨 CRÍTICO: Falta de caixa disponível' : '✅ OK: Reservas disponíveis';
    }
    
    if (k.includes('endiv_geral')) {
      if (value > 70) return '🚨 CRÍTICO: Alavancagem perigosa';
      return value > 50 ? '⚠️ ATENÇÃO: Dívida moderada' : '✅ EXCELENTE: Baixo risco';
    }

    if (k.includes('roe')) {
      return value > 15 ? '✅ EXCELENTE: Retorno alto ao sócio' : '⚠️ ATENÇÃO: Rentabilidade baixa';
    }

    if (k.includes('margem_liquida')) {
      return value < 0 ? '🚨 CRÍTICO: Operação deficitária' : '✅ BOA: Rentabilidade sólida';
    }

    return 'Análise via Emerald Intelligence';
  }

  getAnosProcessados(anosObj: any): string {
    if (!anosObj) return '...';
    return Object.keys(anosObj).sort().join(' VS ');
  }

  formatKey(key: string): string {
    const labels: Record<string, string> = {
      'liq_corrente': 'Liquidez Corrente',
      'liq_seca': 'Liquidez Seca',
      'liq_imediata': 'Liquidez Imediata',
      'roe': 'ROE (Rent. Sócio)',
      'roa': 'ROA (Rent. Ativos)',
      'margem_liquida': 'Margem Líquida',
      'endiv_geral': 'Endividamento Geral'
    };
    return labels[key.toLowerCase()] || key.replace(/_/g, ' ').toUpperCase();
  }

  getFormatType(key: string): 'currency' | 'percent' | 'number' {
    const k = key.toLowerCase();
    if (k.includes('margem') || k.includes('roa') || k.includes('roe') || k.includes('perc') || k.includes('endiv')) return 'percent';
    if (k.includes('ebitda')) return 'currency';
    return 'number';
  }

  onFileSelected(event: any) {
    const files = event.target.files;
    if (files.length) {
      this.financialService.uploadFiles(Array.from(files)).subscribe({
        error: (err: any) => alert('Erro na análise: ' + (err.error?.error || 'Falha no servidor'))
      });
    }
  }

  print() { window.print(); } 
}
